function topoSort(graph) {
  const deps = new Map();
  const tasks = new Set();

  const addTask = (name) => {
    tasks.add(name);
    if (!deps.has(name)) deps.set(name, new Set());
  };

  for (const key of Object.keys(graph)) {
    addTask(key);
    for (const dep of graph[key]) {
      addTask(dep);
      deps.get(key).add(dep);
    }
  }

  const order = [];
  const placed = new Set();
  const remaining = new Set(tasks);

  while (remaining.size > 0) {
    let next = null;
    for (const name of remaining) {
      const d = deps.get(name);
      let ready = true;
      for (const dep of d) {
        if (!placed.has(dep)) {
          ready = false;
          break;
        }
      }
      if (ready) {
        if (next === null || name < next) next = name;
      }
    }

    if (next === null) {
      throw new Error('cycle detected');
    }

    placed.add(next);
    remaining.delete(next);
    order.push(next);
  }

  return order;
}

module.exports = { topoSort };
