function topoSort(graph) {
  const deps = new Map();

  for (const task of Object.keys(graph)) {
    deps.set(task, new Set(graph[task]));
  }

  for (const [task, list] of Object.entries(graph)) {
    for (const dep of list) {
      if (!deps.has(dep)) {
        deps.set(dep, new Set());
      }
    }
  }

  const tasks = new Set(deps.keys());
  const placed = new Set();
  const result = [];

  while (result.length < tasks.size) {
    let next = null;

    for (const task of tasks) {
      if (placed.has(task)) continue;

      let ready = true;
      for (const dep of deps.get(task)) {
        if (!placed.has(dep)) {
          ready = false;
          break;
        }
      }

      if (!ready) continue;

      if (next === null || task < next) {
        next = task;
      }
    }

    if (next === null) {
      throw new Error('cycle detected in dependencies');
    }

    placed.add(next);
    result.push(next);
  }

  return result;
}

