function topoSort(graph) {
  if (graph == null || typeof graph !== 'object') {
    throw new TypeError('graph must be an object');
  }

  const deps = Object.create(null); // task -> Set of dependency names

  function addTask(name) {
    if (!Object.prototype.hasOwnProperty.call(deps, name)) {
      deps[name] = new Set();
    }
  }

  // First pass: keys are tasks with their dependencies.
  for (const key of Object.keys(graph)) {
    addTask(key);
    const list = graph[key];
    if (!Array.isArray(list)) {
      throw new TypeError('dependency list must be an array');
    }
    for (const d of list) {
      addTask(d);
      deps[key].add(d);
    }
  }

  // Second pass: names appearing only inside dependency lists become tasks with no dependencies.
  for (const key of Object.keys(graph)) {
    const list = graph[key];
    if (!Array.isArray(list)) continue;
    for (const d of list) {
      if (!Object.prototype.hasOwnProperty.call(graph, d)) {
        addTask(d);
      }
    }
  }

  const placed = Object.create(null);
  const result = [];
  const allTasks = Object.keys(deps);

  for (let i = 0; i < allTasks.length; i++) {
    let candidate = null;
    for (const t of allTasks) {
      if (placed[t]) continue;
      let ready = true;
      for (const d of deps[t]) {
        if (!placed[d]) {
          ready = false;
          break;
        }
      }
      if (ready) {
        if (candidate === null || t < candidate) {
          candidate = t;
        }
      }
    }
    if (candidate === null) {
      throw new Error('dependency cycle detected');
    }
    placed[candidate] = true;
    result.push(candidate);
  }

  return result;
}

