function topoSort(graph) {
  const deps = new Map();
  const addTask = (name) => {
    if (!deps.has(name)) deps.set(name, new Set());
    return deps.get(name);
  };

  for (const key of Object.keys(graph)) {
    addTask(key);
    const list = graph[key];
    if (!Array.isArray(list)) throw new Error('invalid dependency list');
    for (const dep of list) addTask(dep).add(dep) && deps.get(key).add(dep);
  }

  const placed = new Set();
  const result = [];

  while (placed.size < deps.size) {
    let next = null;
    for (const name of deps.keys()) {
      if (placed.has(name)) continue;
      if ([...deps.get(name)].every((d) => placed.has(d))) {
        if (next === null || name < next) next = name;
      }
    }
    if (next === null) throw new Error('cycle detected');
    placed.add(next);
    result.push(next);
  }

  return result;
}

