_ORDER = ['d', 'h', 'm', 's']


def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    if not text:
        raise ValueError("empty string")

    matches = re.findall(r'(\d+)([a-z])', text)
    if re.sub(r'\d+[a-z]', '', text) != '' or len(re.findall(r'\d+[a-z]', text)) != len(matches):
        raise ValueError("invalid format")

    total = 0
    seen_index = -1
    for digits, unit in matches:
        if unit not in _UNIT_SECONDS:
            raise ValueError("unknown unit")
        idx = _ORDER.index(unit)
        if idx <= seen_index:
            raise ValueError("units must be strictly descending and unique")
        seen_index = idx
        total += int(digits) * _UNIT_SECONDS[unit]
    return total
