function topoSort(graph) {
  const deps = {};
  const indegree = {};
  const addTask = (t) => {
    if (!(t in deps)) {
      deps[t] = new Set();
      indegree[t] = 0;
    }
    return deps[t];
  };

  for (const t of Object.keys(graph)) {
    addTask(t);
  }
  for (const t of Object.keys(graph)) {
    const set = addTask(t);
    for (const d of graph[t]) {
      addTask(d);
      if (!set.has(d)) {
        set.add(d);
        indegree[t] += 1;
      }
    }
  }

  const ready = [];
  for (const t of Object.keys(indegree)) {
    if (indegree[t] === 0) ready.push(t);
  }
  ready.sort();

  const result = [];
  const dependents = {};
  for (const t of Object.keys(deps)) {
    dependents[t] = [];
  }
  for (const t of Object.keys(deps)) {
    for (const d of deps[t]) {
      dependents[d].push(t);
    }
