function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed === '') {
    return [];
  }

  const parts = trimmed.split(',');
  const set = new Set();

  for (const rawPart of parts) {
    const part = rawPart.trim();
    if (part === '') {
      throw new SyntaxError('empty part');
    }

    const dashIndex = part.indexOf('-');
    if (dashIndex !== -1 && part.indexOf('-', dashIndex + 1) !== -1) {
      throw new SyntaxError('more than one dash in part: ' + part);
    }

    if (dashIndex === -1) {
      const value = parseInteger(part, 'single number');
      set.add(value);
    } else {
      const loStr = part.slice(0, dashIndex).trim();
      const hiStr = part.slice(dashIndex + 1).trim();
      const lo = parseInteger(loStr, 'range start');
      const hi = parseInteger(hiStr, 'range end');
      if (lo > hi) {
        throw new RangeError('range start is greater than range end: ' + part);
      }
      for (let i = lo; i <= hi; i++) {
        set.add(i);
      }
    }
  }

  return Array.from(set).sort((a, b) => a - b);
}

function parseInteger(text, label) {
  if (!/^\d+$/.test(text)) {
    throw new SyntaxError('invalid ' + label + ': ' + text);
  }
  const value = Number(text);
  if (!Number.isFinite(value) || value > Number.MAX_SAFE_INTEGER) {
    throw new SyntaxError('number out of range: ' + text);
  }
  return value;
}

module.exports = { expandRanges };
