def roman_to_int(s):
    if not isinstance(s, str):
        raise TypeError('s must be a str')
    if not s:
        raise ValueError('s must not be empty')

    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not all(ch in values for ch in s):
        raise ValueError('s contains invalid characters')

    # Build canonical numeral for each 1..3999 and compare.
    def to_roman(n):
        table = [
            (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
            (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
            (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
        ]
        out = []
        for val, sym in table:
            while n >= val:
                out.append(sym)
                n -= val
        return ''.join(out)

    if not (1 <= len(s) <= 15):
        raise ValueError('s is not a canonical numeral')

    total = 0
    for i, ch in enumerate(s):
        v = values[ch]
        if i + 1 < len(s) and v < values[s[i + 1]]:
            total -= v
        else:
            total += v

    if 0 < total <= 3999 and to_roman(total) == s:
        return total

    raise ValueError('s is not a canonical numeral')
