import re

_NUM = r'(0|[1-9]\d*)'
_IDENT = r'[0-9A-Za-z-]+'
_PRERELEASE = _IDENT + r'(?:\.' + _IDENT + r')*'
_BUILD = _IDENT + r'(?:\.' + _IDENT + r')*'
_VERSION_RE = re.compile(r'^%s\.%s\.%s(?:-(%s))?(?:\+(%s))?$' % (_NUM, _NUM, _NUM, _PRERELEASE, _BUILD))


def compare_versions(a, b):
    def parse(s):
        if not isinstance(s, str):
            raise ValueError('not a version string')
        m = _VERSION_RE.match(s)
        if not m:
            raise ValueError('invalid version: %r' % s)
        major, minor, patch = (int(m.group(i)) for i in (1, 2, 3))
        pre = m.group(4)
        return (major, minor, patch, pre)

    va = parse(a)
    vb = parse(b)

    for x, y in zip(va, vb):
        if x == y:
            continue
        if x is None:
            return 1
        if y is None:
            return -1
        return -1 if x < y else 1

    pa, pb = va[3], vb[3]
    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1

    ia, ib = pa.split('.'), pb.split('.')
    for x, y in zip(ia, ib):
        dx, dy = x.isdigit(), y.isdigit()
        if dx and dy:
            cx, cy = int(x), int(y)
        else:
            cx, cy = x, y
        if dx and not dy:
            return -1
        if dy and not dx:
            return 1
        if cx != cy:
            return -1 if cx < cy else 1
    if len(ia) == len(ib):
        return 0
    return -1 if len(ia) < len(ib) else 1
