function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed === '') {
    return [];
  }

  const parts = trimmed.split(',');
  const result = new Set();

  for (const part of parts) {
    if (part === '') {
      throw new SyntaxError('empty part: "' + spec + '"');
    }

    if (part.includes('-')) {
      const dashParts = part.split('-');
      if (dashParts.length !== 2) {
        throw new SyntaxError('invalid range: "' + part + '"');
      }
      const [loStr, hiStr] = dashParts;
      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('invalid range: "' + part + '"');
      }
      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);
      if (lo > hi) {
        throw new RangeError('range start greater than end: "' + part + '"');
      }
      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      if (!/^\d+$/.test(part)) {
        throw new SyntaxError('invalid number: "' + part + '"');
      }
      result.add(parseInt(part, 10));
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

