        raise TypeError("expected a str")
    if not _ROMAN_PATTERN.match(s):
        raise ValueError(f"invalid Roman numeral: {s!r}")

    total = 0
    for i, ch in enumerate(s):
        value = _ROMAN_VALUES[ch]
        if i + 1 < len(s) and value < _ROMAN_VALUES[s[i + 1]]:
            total -= value
        else:
            total += value
