function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed === '') {
    return [];
  }

  const parts = trimmed.split(',');
  const seen = new Set();

  for (const rawPart of parts) {
    const part = rawPart.trim();
    if (part === '') {
      throw new SyntaxError('empty part');
    }

    if (part.includes('-')) {
      const dashCount = part.split('-').length - 1;
      if (dashCount !== 1) {
        throw new SyntaxError('more than one dash: ' + part);
      }
      const [loStr, hiStr] = part.split('-');
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('missing end or start: ' + part);
      }
      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('invalid number in range: ' + part);
      }
      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);
      if (lo > hi) {
        throw new RangeError('range start greater than end: ' + part);
      }
      for (let n = lo; n <= hi; n++) {
        seen.add(n);
      }
    } else {
      if (!/^\d+$/.test(part)) {
        throw new SyntaxError('invalid number: ' + part);
      }
      seen.add(parseInt(part, 10));
    }
  }

  return Array.from(seen).sort((a, b) => a - b);
}

module.exports = { expandRanges };
