_BUILD_ID = r'[0-9A-Za-z-]+'
_BUILD = r'(?:' + _BUILD_ID + r'(?:\.' + _BUILD_ID + r')*)'

_VERSION_RE = re.compile(
    r'^' + _NUM + r'\.' + _NUM + r'\.' + _NUM +
    r'(?:-(' + _PRE + r'))?' +
