function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed === '') {
    return [];
  }

  const parts = trimmed.split(',');
  const seen = new Set();

  for (const part of parts) {
    const p = part.trim();
    if (p === '') {
      throw new SyntaxError('empty part');
    }

    if (p.includes('-')) {
      const dashParts = p.split('-');
      if (dashParts.length !== 2) {
        throw new SyntaxError('malformed range: ' + p);
      }
      const [loStr, hiStr] = dashParts;
      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('malformed range: ' + p);
      }
      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);
      if (lo > hi) {
        throw new RangeError('range start greater than end: ' + p);
      }
      for (let n = lo; n <= hi; n++) {
        seen.add(n);
      }
    } else {
      if (!/^\d+$/.test(p)) {
        throw new SyntaxError('malformed part: ' + p);
      }
      seen.add(parseInt(p, 10));
    }
  }

  return Array.from(seen).sort((a, b) => a - b);
}

module.exports = { expandRanges };
