def _parse(version):
    m = _VER_RE.match(version)
    if not m:
        raise ValueError("invalid version: %r" % version)
    major = int(m.group("major"))
    minor = int(m.group("minor"))
    patch = int(m.group("patch"))
    pre = m.group("prerelease")
    prerelease = None
    if pre is not None:
        prerelease = []
        for ident in pre[1:].split("."):
            if ident == "":
                raise ValueError("invalid version: %r" % version)
            if re.fullmatch(r"[0-9]+", ident):
                if len(ident) > 1 and ident[0] == "0":
                    raise ValueError("invalid version: %r" % version)
                prerelease.append((0, int(ident), None))
            else:
                prerelease.append((1, None, ident))
