    for i in range(n):
        a = p1[i]
        b = p2[i]
        if a[0] != b[0]:
            return -1 if a[0] < b[0] else 1
        if a[0] == 0:
            if a[1] != b[1]:
                return -1 if a[1] < b[1] else 1
        else:
            if a[2] != b[2]:
                return -1 if a[2] < b[2] else 1
    return 0 if len(p1) == len(p2) else (-1 if len(p1) < len(p2) else 1)


