function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed === '') return [];

  const parts = trimmed.split(',');
  const seen = new Set();
  const result = [];

  for (const part of parts) {
    const p = part.trim();
    if (p === '') {
      throw new SyntaxError('empty part');
    }

    const dashCount = (p.match(/-/g) || []).length;
    if (dashCount > 1) {
      throw new SyntaxError('more than one dash');
    }

    let values;
    if (dashCount === 1) {
      const [loStr, hiStr] = p.split('-');
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('missing number in range');
      }
      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);
      if (!Number.isInteger(lo) || !Number.isInteger(hi) || lo < 0 || hi < 0) {
        throw new SyntaxError('invalid range bounds');
      }
      if (lo > hi) {
        throw new RangeError('range start is greater than range end');
      }
      values = [];
      for (let i = lo; i <= hi; i++) values.push(i);
    } else {
      const n = parseInt(p, 10);
      if (!Number.isInteger(n) || n < 0) {
        throw new SyntaxError('invalid number');
      }
      values = [n];
    }

    for (const v of values) {
      if (!seen.has(v)) {
        seen.add(v);
        result.push(v);
      }
    }
  }

  return result.sort((a, b) => a - b);
}

module.exports = { expandRanges };
