function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed.length === 0) {
    return [];
  }

  const parts = trimmed.split(',');
  const seen = new Set();
  const result = [];

  const addNumber = (n) => {
    if (!seen.has(n)) {
      seen.add(n);
      result.push(n);
    }
  };

  for (const part of parts) {
    if (part.length === 0) {
      throw new SyntaxError('empty part in spec');
    }

    const match = part.match(/^(\d+)(?:-(\d+))?$/);
    if (!match) {
      throw new SyntaxError(`malformed part "${part}"`);
    }

    const lo = parseInt(match[1], 10);
    if (match[2] === undefined) {
      addNumber(lo);
    } else {
      const hi = parseInt(match[2], 10);
      if (lo > hi) {
        throw new RangeError(`range start ${lo} is greater than end ${hi}`);
      }
      for (let n = lo; n <= hi; n++) {
        addNumber(n);
      }
    }
  }

  result.sort((a, b) => a - b);
  return result;
}

