        rest, build = rest.split('+', 1)
        if not build or '.' in build and any(p == '' for p in build.split('.')):
            raise ValueError('invalid version')
        if not all(re.fullmatch(r'[0-9A-Za-z-]+', p) for p in build.split('.')):
            raise ValueError('invalid version')
