        if not pre:
            raise ValueError('invalid version')
        parts = pre.split('.')
        if any(p == '' for p in parts):
            raise ValueError('invalid version')
        for p in parts:
            if not re.fullmatch(r'[0-9A-Za-z-]+', p):
                raise ValueError('invalid version')
            if _NUMERIC.fullmatch(p) is not None:
                if len(p) > 1 and p[0] == '0':
                    raise ValueError('invalid version')
    else:
