  }

  on(event, fn) {
    if (typeof fn !== 'function') throw new TypeError('fn must be a function');
    let list = this._map.get(event);
    if (!list) { list = []; this._map.set(event, list); }
    list.push({ fn, once: false });
    return this;
  }

  once(event, fn) {
    if (typeof fn !== 'function') throw new TypeError('fn must be a function');
    let list = this._map.get(event);
    if (!list) { list = []; this._map.set(event, list); }
    list.push({ fn, once: true });
    return this;
  }

  off(event, fn) {
    const list = this._map.get(event);
    if (list) {
      this._map.set(event, list.filter(r => r.fn !== fn));
    }
    return this;
  }

  emit(event, ...args) {
    const list = this._map.get(event);
    if (!list || list.length === 0) return false;
    const snapshot = list.slice();
    for (const reg of snapshot) {
      if (reg.once) this.off(event, reg.fn);
      reg.fn.apply(this, args);
    }
    return true;
  }

  listenerCount(event) {
    const list = this._map.get(event);
    return list ? list.length : 0;
  }
}

