function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed === '') {
    return [];
  }

  const parts = trimmed.split(',');
  const set = new Set();

  for (const part of parts) {
    const p = part.trim();

    if (p === '') {
      throw new SyntaxError('empty part');
    }

    const dashCount = (p.match(/-/g) || []).length;

    if (dashCount === 1) {
      const [loStr, hiStr] = p.split('-');

      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('missing range endpoint');
      }

      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('invalid number in range');
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (lo > hi) {
        throw new RangeError('range start is greater than its end');
      }

      for (let i = lo; i <= hi; i++) {
        set.add(i);
      }
    } else if (dashCount === 0) {
      if (!/^\d+$/.test(p)) {
        throw new SyntaxError('invalid number');
      }

      set.add(parseInt(p, 10));
    } else {
      throw new SyntaxError('more than one dash');
    }
  }

  return Array.from(set).sort((a, b) => a - b);
}

module.exports = { expandRanges };
