  const numbers = new Set();

  for (const part of parts) {
    const p = part.trim();
    if (p === '') {
      throw new SyntaxError('empty part');
    }

    const dashCount = (p.match(/-/g) || []).length;
    if (dashCount > 1) {
      throw new SyntaxError('more than one dash');
    }

    if (dashCount === 0) {
      if (!/^\d+$/.test(p)) {
        throw new SyntaxError('invalid number: ' + p);
      }
      numbers.add(parseInt(p, 10));
    } else {
      const [loStr, hiStr] = p.split('-');
      if (loStr === '' || hiStr === '' || !/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('invalid range: ' + p);
      }
      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);
      if (lo > hi) {
        throw new RangeError('range start must not exceed end: ' + p);
      }
      for (let i = lo; i <= hi; i++) {
        numbers.add(i);
      }
    }
  }

  return Array.from(numbers).sort((a, b) => a - b);
}

