class Emitter {
  constructor() {
    this._listeners = new Map();
  }

  _getListeners(event) {
    let list = this._listeners.get(event);
    if (list === undefined) {
      list = [];
      this._listeners.set(event, list);
    }
    return list;
  }

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    this._getListeners(event).push(fn);
    return this;
  }

  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    const self = this;
    const wrapper = function (...args) {
      self.off(event, wrapper);
      return fn.apply(self, args);
    };
    wrapper.listener = fn;
    this._getListeners(event).push(wrapper);
    return this;
  }

  off(event, fn) {
    const list = this._listeners.get(event);
    if (list) {
      this._listeners.set(
        event,
        list.filter((l) => l !== fn && l.listener !== fn)
      );
    }
    return this;
  }

  emit(event, ...args) {
    const list = (this._listeners.get(event) || []).slice();
    for (const fn of list) {
      fn.apply(this, args);
    }
    return list.length > 0;
  }

  listenerCount(event) {
    const list = this._listeners.get(event);
    return list ? list.length : 0;
  }
}

