function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const trimmed = spec.trim();
  if (trimmed === '') {
    return [];
  }

  const parts = trimmed.split(',');
  const seen = new Set();

  for (const part of parts) {
    const p = part.trim();

    if (p === '') {
      throw new SyntaxError('empty part');
    }

    if (p.includes('-')) {
      const segs = p.split('-');
      if (segs.length !== 2) {
        throw new SyntaxError('more than one dash');
      }
      const [loStr, hiStr] = segs;
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('missing endpoint');
      }
      if (!/^[0-9]+$/.test(loStr) || !/^[0-9]+$/.test(hiStr)) {
        throw new SyntaxError('invalid integer in range');
      }
      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);
      if (lo > hi) {
        throw new RangeError('range start greater than end');
      }
      for (let n = lo; n <= hi; n++) {
        seen.add(n);
      }
    } else {
      if (!/^[0-9]+$/.test(p)) {
        throw new SyntaxError('invalid integer');
      }
      seen.add(parseInt(p, 10));
    }
  }

  return Array.from(seen).sort((a, b) => a - b);
}

module.exports = { expandRanges };
