'use strict';

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

function isLeapYear(y) {
  return y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0);
}

function daysInMonth(y, m) {
  const table = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (m === 2 && isLeapYear(y)) return 29;
  return table[m - 1];
}

function addDays(dateStr, days) {
  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }
  if (typeof days !== 'number' || !Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }

  const m = DATE_RE.exec(dateStr);
  if (!m) {
    throw new RangeError('dateStr has the wrong shape');
  }
  const year = parseInt(m[1], 10);
  const month = parseInt(m[2], 10);
  const day = parseInt(m[3], 10);

  if (year < 1 || year > 9999) {
    throw new RangeError('year out of range 0001..9999');
  }
  if (month < 1 || month > 12) {
    throw new RangeError('month out of range');
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    throw new RangeError('not a real calendar date');
  }

  const utcMs = Date.UTC(year, month - 1, day);
  const resultMs = utcMs + days * 86400000;
  const dt = new Date(resultMs);
  const ry = dt.getUTCFullYear();
  const rm = dt.getUTCMonth() + 1;
  const rd = dt.getUTCDate();

  if (ry < 1 || ry > 9999) {
    throw new RangeError('result year out of range 0001..9999');
  }

  const yy = String(ry).padStart(4, '0');
  const mm = String(rm).padStart(2, '0');
  const dd = String(rd).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

module.exports = { addDays };
