        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines = []
    current = []
    current_len = 0

    for word in words:
        if not current:
            current = [word]
            current_len = len(word)
            continue

        extra = 1 + len(word)
        if current_len + extra <= width:
            current.append(word)
            current_len += extra
        else:
            lines.append(" ".join(current))
            current = [word]
            current_len = len(word)

