function addDays(dateStr, days) {
  if (typeof dateStr !== 'string') throw new TypeError('dateStr must be a string');
  if (typeof days !== 'number' || !Number.isInteger(days)) throw new TypeError('days must be an integer');

  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!m) throw new RangeError('invalid date format');

  let y = parseInt(m[1], 10);
  let mo = parseInt(m[2], 10);
  let d = parseInt(m[3], 10);

  if (y < 1 || y > 9999) throw new RangeError('year out of range');
  if (mo < 1 || mo > 12) throw new RangeError('month out of range');
  if (d < 1 || d > daysInMonth(y, mo)) throw new RangeError('day out of range');

  // Normalize to epoch day count (days since year 1-01-01 in proleptic Gregorian)
  let totalDays = 0;
  for (let yy = 1; yy < y; yy++) totalDays += isLeapYear(yy) ? 366 : 365;
  for (let mm = 1; mm < mo; mm++) totalDays += daysInMonth(y, mm);
  totalDays += d - 1;

  totalDays += days;

  // Convert back to Y-M-D
  let ny = 1;
  while (ny <= 9999) {
    const yd = isLeapYear(ny) ? 366 : 365;
    if (totalDays < yd) break;
    totalDays -= yd;
    ny++;
  }
  if (ny > 9999) throw new RangeError('year out of range');

  let nm = 1;
  while (nm <= 12) {
    const md = daysInMonth(ny, nm);
    if (totalDays < md) break;
    totalDays -= md;
    nm++;
  }
  const nd = totalDays + 1;

  return `${pad(ny, 4)}-${pad(nm, 2)}-${pad(nd, 2)}`;
}

