    end = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                if start is not None:
                    raise ValueError("exactly one S expected")
                start = (r, c)
            elif grid[r][c] == 'E':
                if end is not None:
                    raise ValueError("exactly one E expected")
                end = (r, c)

    if start is None or end is None:
        raise ValueError("grid must contain exactly one S and exactly one E")

    if start == end:
        return 0

    visited = [[False] * cols for _ in range(rows)]
    q = deque()
    q.append((start[0], start[1], 0))
    visited[start[0]][start[1]] = True

    while q:
        r, c, d = q.popleft()
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] != '#':
                if (nr, nc) == end:
                    return d + 1
                visited[nr][nc] = True
                q.append((nr, nc, d + 1))

    return -1
