            raise ValueError("rows must have equal length")

    start = end = None
    for r in range(rows):
        for c in range(width):
            ch = grid[r][c]
            if ch not in "SE# .":
                raise ValueError("invalid character")
            if ch == 'S':
                if start is not None:
                    raise ValueError("exactly one S required")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("exactly one E required")
                end = (r, c)

    if start is None or end is None:
        raise ValueError("exactly one S and one E required")

    dist = [[-1] * width for _ in range(rows)]
    dist[start[0]][start[1]] = 0
    q = deque([start])
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    while q:
        r, c = q.popleft()
        d = dist[r][c]
        if (r, c) == end:
            return d
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < width and dist[nr][nc] == -1 and grid[nr][nc] != '#':
                dist[nr][nc] = d + 1
                q.append((nr, nc))
