  let result = first.slice(0, prefixLength);
  const lastCodeUnit = result.charCodeAt(result.length - 1);
  if (lastCodeUnit >= 0xDC00 && lastCodeUnit <= 0xDFFF) {
    result = result.slice(0, -1);
  }
  return result;
