    }
  }

  if (strs.length === 0) return '';
  if (strs.length === 1) return strs[0];
  if (strs.some((s) => s.length === 0)) return '';

  const first = strs[0];
  let end = first.length;

  for (let i = 1; i < strs.length; i++) {
    const s = strs[i];
    let j = 0;
    while (j < end && j < s.length && first[j] === s[j]) j++;
    end = j;
