import calendar
import datetime


def add_months(date_str, n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")

    try:
        year, month, day = map(int, date_str.split("-"))
    except (ValueError, AttributeError):
        raise ValueError("date_str is not a valid ISO date")

    if len(date_str) != 10 or date_str[4] != "-" or date_str[7] != "-":
        raise ValueError("date_str is not a valid ISO date")

    try:
        datetime.date(year, month, day)
    except ValueError:
        raise ValueError("date_str is not a valid date")

    total = (year * 12 + (month - 1)) + n
    new_year = total // 12
    new_month = total % 12 + 1

    if not 1 <= new_year <= 9999:
        raise ValueError("result year out of range 1..9999")

    last_day = calendar.monthrange(new_year, new_month)[1]
    new_day = min(day, last_day)

    return "{:04d}-{:02d}-{:02d}".format(new_year, new_month, new_day)
