from collections import deque

def maze_steps(grid):
    if not grid:
        raise ValueError("grid must be non-empty")

    cols = len(grid[0])
    if any(len(row) != cols for row in grid):
        raise ValueError("rows are not all the same length")

    rows = len(grid)
    start = None
    end = None
    valid = set("SE#.")

    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch not in valid:
                raise ValueError(f"invalid character {ch!r}")
            if ch == "S":
                if start is not None:
                    raise ValueError("more than one S")
                start = (r, c)
            elif ch == "E":
                if end is not None:
                    raise ValueError("more than one E")
                end = (r, c)

    if start is None:
        raise ValueError("no S found")
    if end is None:
        raise ValueError("no E found")

    if start == end:
        return 0

    visited = [[False] * cols for _ in range(rows)]
    visited[start[0]][start[1]] = True
    q = deque()
    q.append((start[0], start[1], 0))

    while q:
        r, c, dist = q.popleft()
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] != "#":
                    if (nr, nc) == end:
                        return dist + 1
                    visited[nr][nc] = True
                    q.append((nr, nc, dist + 1))

    return -1
